+import java.io.File;
+import lombok.DirectoryRunner;
+import lombok.RunTestsViaDelombok;
+import lombok.transform.TestLombokFilesIdempotent;
+import lombok.transform.TestWithDelombok;
+
+public class FieldDefaultsCheck {
+    public static void main(String[] args) throws Throwable {
+        int count = 0;
+        DirectoryRunner.TestParams[] suites = {
+            new TestWithDelombok(), new TestLombokFilesIdempotent()
+        };
+        for (DirectoryRunner.TestParams suite : suites) {
+            for (File file : suite.getBeforeDirectory().listFiles()) {
+                if (!file.getName().startsWith("FieldDefaults")) continue;
+                new RunTestsViaDelombok().createTester(suite, file, "javac", 17).runTest();
+                System.out.println("PASS " + suite.testNamePrefix() + file.getName());
+                count++;
+            }
+        }
+        System.out.println(count + " field-defaults checks passed");
+    }
+}
PATCH
